inline void doc::row_Reserve(i64 n) {
    u64 new_n = _db.row_n + n;
    if (UNLIKELY(new_n > _db.row_max)) {
        row_AbsReserve(new_n);
    }
}

// --- doc.FDb.row.qFind
// 'quick' Access row by row id. No bounds checking.
inline doc::Row& doc::row_qFind(u64 t) {
    return _db.row_elems[t];
}

// --- doc.FDb.row.qLast
// Return reference to last element of array. No bounds checking
inline doc::Row& doc::row_qLast() {
    return row_qFind(u64(_db.row_n-1));
}

// --- doc.FDb.row.rowid_Get
// Return row id of specified element
inline u64 doc::row_rowid_Get(doc::Row &elem) {
    u64 id = &elem - _db.row_elems;
    return u64(id);
}

// --- doc.FDb.link.EmptyQ
// Return true if index is empty
inline bool doc::link_EmptyQ() {
    return _db.link_n == 0;
}

// --- doc.FDb.link.Find
// Look up row by row id. Return NULL if out of range
inline doc::FLink* doc::link_Find(u64 t) {
    doc::FLink *retval = NULL;
    if (LIKELY(u64(t) < u64(_db.link_n))) {
        u64 x = t + 1;
        u64 bsr   = algo::u64_BitScanReverse(x);
        u64 base  = u64(1)<<bsr;
        u64 index = x-base;
        retval = &_db.link_lary[bsr][index];
    }
    return retval;
}

