// --- doc.FRun.ary.Find
// Look up row by row id. Return NULL if out of range
inline doc::Cell* doc::ary_Find(doc::FRun& parent, u64 t) {
    u64 idx = t;
    u64 lim = parent.ary_n;
    if (idx >= lim) return NULL;
    return parent.ary_elems + idx;
}

// --- doc.FRun.ary.Getary
// Return array pointer by value
inline algo::aryptr<doc::Cell> doc::ary_Getary(const doc::FRun& parent) {
    return algo::aryptr<doc::Cell>(parent.ary_elems, parent.ary_n);
}

// --- doc.FRun.ary.Last
