// --- doc.Key..UpdateMax
// Attempt to make LHS bigger. Return true if it was changed
inline bool doc::Key_UpdateMax(doc::Key &lhs, doc::Key rhs) {
    bool retval = lhs < rhs;
    if (retval) {
        lhs = rhs;
    }
    return retval;
}

// --- doc.Key..Min
// Return the lesser of two values
inline doc::Key doc::Key_Min(doc::Key lhs, doc::Key rhs) {
    return lhs < rhs ? lhs : rhs;
}

// --- doc.Key..UpdateMin
// Attempt to make LHS smaller. Return true if it was changed
inline bool doc::Key_UpdateMin(doc::Key &lhs, doc::Key rhs) {
    bool retval = rhs < lhs;
    if (retval) {
        lhs = rhs;
    }
    return retval;
}

// --- doc.Key..Max
// Return the greater of two values
inline doc::Key doc::Key_Max(doc::Key lhs, doc::Key rhs) {
    return rhs < lhs ? lhs : rhs;
}

// --- doc.Key..Eq
inline bool doc::Key_Eq(doc::Key lhs, doc::Key rhs) {
    bool retval = true;
    retval = u16_Eq(lhs.value, rhs.value);
    return retval;
}

// --- doc.Key..Update
// Set value. Return true if new value is different from old value.
inline bool doc::Key_Update(doc::Key &lhs, doc::Key rhs) {
    bool ret = !Key_Eq(lhs, rhs); // compare values
    if (ret) {
        lhs = rhs; // update
    }
    return ret;
}

