// --- doc.WidthAry.ary.rowid_Get
// Return row id of specified element
inline u64 doc::ary_rowid_Get(doc::WidthAry& parent, i32 &elem) {
    u64 id = &elem - parent.ary_elems;
    return u64(id);
}

// --- doc.WidthAry.ary_curs.Next
// proceed to next item
inline void doc::WidthAry_ary_curs_Next(WidthAry_ary_curs &curs) {
    curs.index++;
}

// --- doc.WidthAry.ary_curs.Reset
inline void doc::WidthAry_ary_curs_Reset(WidthAry_ary_curs &curs, doc::WidthAry &parent) {
    curs.elems = parent.ary_elems;
    curs.n_elems = parent.ary_n;
    curs.index = 0;
}

// --- doc.WidthAry.ary_curs.ValidQ
// cursor points to valid item
inline bool doc::WidthAry_ary_curs_ValidQ(WidthAry_ary_curs &curs) {
    return curs.index < curs.n_elems;
}

// --- doc.WidthAry.ary_curs.Access
// item access
inline i32& doc::WidthAry_ary_curs_Access(WidthAry_ary_curs &curs) {
    return curs.elems[curs.index];
}

// --- doc.WidthAry..Init
// Set all fields to initial values.
inline void doc::WidthAry_Init(doc::WidthAry& parent) {
    parent.ary_elems 	= 0; // (doc.WidthAry.ary)
    parent.ary_n     	= 0; // (doc.WidthAry.ary)
    parent.ary_max   	= 0; // (doc.WidthAry.ary)
}

// --- doc.WidthAry..Ctor
inline  doc::WidthAry::WidthAry() {
    doc::WidthAry_Init(*this);
}

// --- doc.WidthAry..Dtor
inline  doc::WidthAry::~WidthAry() {
    doc::WidthAry_Uninit(*this);
}

